/**
 * The region this application's CICS programs run in (#4343): every program's facade (handleTransaction,
 * handleLink) runs its task here -- one temporary storage, and a LINK / XCTL reaching the other programs
 * through their services' runTask, as the CSD-defined programs of a CICS region reach each other. Spring makes
 * it once, which deploys it (CicsTask.deploy); a test harness joins a region of its own instead (CicsTask.join).
 * Its clock is the mainframe's, as MainframeClock's (#3824): `gitgalaxy.clock` (an ISO local date-time) when
 * set, else the wall clock in `gitgalaxy.zone`, else `gitgalaxy.culture.zone`, else UTC -- never the JVM's.
 */
@Component
public class CicsRegion implements CicsTask.Programs {

    static final Set<String> PROGRAMS = Set.of("ABNDPROC", "ACCTCTRL", "BNK1CAC", "BNK1CCA", "BNK1CCS", "BNK1CRA", "BNK1DAC", "BNK1DCS", "BNK1TFN", "BNK1UAC", "BNKMENU", "CRDTAGY1", "CRDTAGY2", "CRDTAGY3", "CRDTAGY4", "CRDTAGY5", "CREACC", "CRECUST", "CUSTCTRL", "DBCRFUN", "DELACC", "DELCUS", "GETCOMPY", "GETSCODE", "INQACC", "INQACCCU", "INQCUST", "UPDACC", "UPDCUST", "XFRFUN");
    static final Set<String> TRANSACTIONS = Set.of("OCAC", "OCCA", "OCCS", "OCR1", "OCR2", "OCR3", "OCR4", "OCR5", "OCRA", "ODAC", "ODCS", "OMEN", "OTFN", "OUAC");

    private final ApplicationContext context;

    public CicsRegion(ApplicationContext context, @Value("${gitgalaxy.clock:}") String pinned,
                      @Value("${gitgalaxy.zone:${gitgalaxy.culture.zone:UTC}}") String zoneId) {
        this.context = context;
        ZoneId zone = ZoneId.of(zoneId == null || zoneId.isBlank() ? "UTC" : zoneId.trim());
        String at = pinned == null ? "" : pinned.trim();
        CicsTask.deploy(new CicsTask.LocalRegion(this, null,
                at.isEmpty() ? () -> LocalDateTime.now(zone) : () -> LocalDateTime.parse(at)));
    }

    @Override
    public boolean defined(String program) {
        return PROGRAMS.contains(program);
    }

    @Override
    public boolean transaction(String transid) {
        return TRANSACTIONS.contains(transid);
    }

    @Override
    public void run(String program, CicsTask task) {
        switch (program) {
            case "ABNDPROC" -> context.getBean(AbndprocService.class).runTask(task);
            case "ACCTCTRL" -> context.getBean(AcctctrlService.class).runTask(task);
            case "BNK1CAC" -> context.getBean(Bnk1cacService.class).runTask(task);
            case "BNK1CCA" -> context.getBean(Bnk1ccaService.class).runTask(task);
            case "BNK1CCS" -> context.getBean(Bnk1ccsService.class).runTask(task);
            case "BNK1CRA" -> context.getBean(Bnk1craService.class).runTask(task);
            case "BNK1DAC" -> context.getBean(Bnk1dacService.class).runTask(task);
            case "BNK1DCS" -> context.getBean(Bnk1dcsService.class).runTask(task);
            case "BNK1TFN" -> context.getBean(Bnk1tfnService.class).runTask(task);
            case "BNK1UAC" -> context.getBean(Bnk1uacService.class).runTask(task);
            case "BNKMENU" -> context.getBean(BnkmenuService.class).runTask(task);
            case "CRDTAGY1" -> context.getBean(Crdtagy1Service.class).runTask(task);
            case "CRDTAGY2" -> context.getBean(Crdtagy2Service.class).runTask(task);
            case "CRDTAGY3" -> context.getBean(Crdtagy3Service.class).runTask(task);
            case "CRDTAGY4" -> context.getBean(Crdtagy4Service.class).runTask(task);
            case "CRDTAGY5" -> context.getBean(Crdtagy5Service.class).runTask(task);
            case "CREACC" -> context.getBean(CreaccService.class).runTask(task);
            case "CRECUST" -> context.getBean(CrecustService.class).runTask(task);
            case "CUSTCTRL" -> context.getBean(CustctrlService.class).runTask(task);
            case "DBCRFUN" -> context.getBean(DbcrfunService.class).runTask(task);
            case "DELACC" -> context.getBean(DelaccService.class).runTask(task);
            case "DELCUS" -> context.getBean(DelcusService.class).runTask(task);
            case "GETCOMPY" -> context.getBean(GetcompyService.class).runTask(task);
            case "GETSCODE" -> context.getBean(GetscodeService.class).runTask(task);
            case "INQACC" -> context.getBean(InqaccService.class).runTask(task);
            case "INQACCCU" -> context.getBean(InqacccuService.class).runTask(task);
            case "INQCUST" -> context.getBean(InqcustService.class).runTask(task);
            case "UPDACC" -> context.getBean(UpdaccService.class).runTask(task);
            case "UPDCUST" -> context.getBean(UpdcustService.class).runTask(task);
            case "XFRFUN" -> context.getBean(XfrfunService.class).runTask(task);
            default -> throw new IllegalStateException("no service runs program " + program);
        }
    }
}
